  str_book_pet_tag_friend_60 = "Línea de defensa Illumina",
  str_book_pet_tag_friend_61 = "Utopía Submarina",
  str_book_pet_tag_friend_62 = "Matón Umbraton",
  str_book_pet_tag_friend_65 = "Arma Biológica",
