  str_book_season_cg_active = "DNT",
  str_book_unlock_desc_20001 = "Obtenido tras leer la precuela de N1-Sueño Bizarro en Despertar en la Tormenta",
  str_book_unlock_desc_20002 = "Obtenido al adquirir el Sketchbook completo coleccionable en Awakening in the Storm",
  str_book_unlock_desc_20003 = "Obtenido tras leer la precuela de N1-Sueño Bizarro en Despertar en la Tormenta",
  str_book_unlock_desc_20004 = "Obtenido después de leer la precuela de N7-Red Hound en Awakening in the Storm",
  str_book_unlock_desc_20005 = "Obtenido después de leer la secuela de N8-Catch Fire en Awakening in the Storm",
  str_book_unlock_desc_20006 = "Obtenido al adquirir el Sketchbook completo coleccionable en Awakening in the Storm",
  str_book_unlock_desc_20007 = "Obtenido al adquirir el Sketchbook completo coleccionable en Awakening in the Storm",
  str_book_unlock_desc_20101 = "Obtenido después de leer la precuela de N1 - Caballero en Pruebas Entre Ondas Doradas.",
  str_book_unlock_desc_20102 = "Obtenido después de leer la precuela de N10 - Conspiración Rebelde en Juicios Entre Ondas Doradas.",
  str_book_unlock_desc_20103 = "Obtenido después de leer la secuela de N15 - Juicio Final en Pruebas Entre Ondas Doradas.",
  str_book_unlock_desc_20104 = "Obtenido después de leer la precuela de N1 - Caballero en Pruebas Entre Ondas Doradas.",
  str_book_unlock_desc_20105 = "Obtenido después de leer la precuela de N14 - La Reflexión en Pruebas entre Ondas Doradas.",
  str_book_unlock_desc_20106 = "Obtenido después de leer la precuela de N14 - La Reflexión en Pruebas entre Ondas Doradas.",
  str_book_unlock_desc_20107 = "Obtenido después de leer la secuela de N15 - Juicio Final en Pruebas Entre Ondas Doradas.",
  str_book_unlock_desc_20108 = "Obtenido después de leer la secuela de N15 - Juicio Final en Pruebas Entre Ondas Doradas.",
  str_book_title_skin_10068 = "Invitación Achispada",
  str_book_skin_info_10068 = "\"El tiempo de una bruja es valioso y no puedo esperar, tsk-tsk.\"\nDespués de beber una poción mágica, Uriel de repente se vuelve proactivo, no solo acorralándote sino también intentando algo aún más temible...",
  str_book_title_skin_10069 = "Campanas en el Crepúsculo",
  str_book_skin_info_10069 = "\"Acabo de darme cuenta, y realmente fue hace un segundo, que el vacío podría llenarse.\"\nEl calor de las llamas difumina la figura de la bruja. Pero, ¿cuál de ella te está confesando ahora mismo?",
  str_book_title_skin_10067 = "La Sensibilidad de Axelia",
  str_book_skin_info_10067 = "Una sensación mágica ha golpeado a Axelia, entrelazando su yo fracturado con la rosa confinada en el frasco de vidrio. Esta inexplicable oleada de emoción en realidad señala los cambios incipientes en su mentalidad.",
  str_book_title_skin_10070 = "Apreciado",
  str_book_skin_info_10070 = "\"¡Era un campo de trigo! Lleno de granos dorados y ondulantes, ¡y yo estaba de pie en él! Junto a mí había una dama gentil cuyo rostro no me era claro, pero ella me sonreía. Muchos niños corrían a nuestro alrededor... Su risa resonaba por el campo como una canción.\"",
  str_book_title_skin_10071 = "Testigo del Ídolo del Dragón",
  str_book_title_skin_10072 = "La Siesta del Mediodía de Robyn",
  str_book_skin_info_10071 = "\"Puede que sea un poco arrogante de mi parte decirlo, pero realmente espero poder convertirme en alguien en quien puedas confiar.\"\nBajo el testigo del ídolo del dragón, extiendes una invitación a Sharona.",
  str_book_skin_info_10072 = "Perdida en el mundo de los libros, Robyn se queda dormida en la mesa. El sol del mediodía es radiante, pero su sueño no se ve perturbado.",
  str_book_info1108 = "Deseo",
  str_book_info1109 = "Destruye la oscuridad",
  str_book_info1110 = "Refugio",
  str_book_info1111 = "Refugio - Faro",
  str_book_info1112 = "Juramentos en la Cresta",
  str_book_title1108 = "Cargando con un deber inefable, se arrodilla frente al altar, su tristeza no expresada pero profundamente sentida, ofreciendo fervientes oraciones a lo divino. Este misterioso y conmovedor ritual se desarrolla como una melancólica obra maestra.",
  str_book_title1109 = "En medio de la oscuridad, ella salta como un rayo, su lanza se hunde sin piedad en el cráneo del enemigo. Con una ferocidad y fuerza indomables, sacude la misma tierra, sus ojos arden con un odio vengativo que abrasa a sus adversarios.",
  str_book_title1110 = "Guiado por el espíritu de las montañas, el poder de la naturaleza fluye hacia la base, y racimos de luz fluyente brotan de los tocones de los árboles, iluminando el vasto altar. Así, los espíritus largamente silenciados son despertados.",
  str_book_title1111 = "En un instante, tres antiguos pinos de nieve brotan en un árbol gigante como un faro, su resplandor radiante ilumina toda la caverna, con el rayo más suave infundiendo la lanza de Tiare.",
  str_book_title1112 = [[
"Para erigir faros a lo largo del camino por delante."
La bandera ondeante da testimonio y los anima, llevando sus promesas a tierras lejanas.]],
  str_book_title_skin_10073 = "Luz de Fluorita",
  str_book_skin_info_10073 = "Charlas hasta tarde en la noche con Fleur sobre minerales cuando el mineral emite un tenue resplandor, espera, ¿por qué sigue caliente? Juzgando por la cara de Fleur, ¿podría tener fiebre?",
  str_book_title_skin_10074 = "Juegos de Dormitorio",
  str_book_skin_info_10074 = "\"¡Ahora que te he atrapado, tienes que tocar el corazón en la mesa para liberarte!\"",
  str_book_title_skin_10075 = "Noche estrellada sin sueño",
  str_book_skin_info_10075 = "\"¡Con tú a mi lado, no importa cuán oscuro sea, no creo que tenga nada que temer!\"",
  str_book_title_skin_10077 = "La Bella Durmiente y el Príncipe",
  str_book_skin_info_10077 = "\"¿Sigo soñando? Todo se siente demasiado real, desde tu calor hasta tu aliento...\"",
  str_book_title_skin_10078 = "Hagámoslo",
  str_book_skin_info_10078 = "La puerta se abre de repente, interrumpiendo los pasos vacilantes de la chica. En ese caso, solo puede armarse de valor y avanzar con la cabeza bien alta. La chica aprieta los labios, decidida a no dejar que nadie vea su confusión y desamparo.",
  str_book_title_skin_10079 = "Danza de Caracol de Río de la Doncella Dragón",
  str_book_skin_info_10079 = "\"Al realizar su danza sagrada aquí, los caracoles harán lo que ordene por reverencia.\"",
  str_book_title_skin_10080 = "Bestia enjaulada",
  str_book_skin_info_10080 = "Hydrad se ha infiltrado solo en sus filas y confía en que vengas con refuerzos.",
  str_book_title_skin_10081 = "Diminuta Deidad",
  str_book_skin_info_10081 = "\"Tu ofrenda me agradó mucho. Habla tu deseo, y yo lo concederé para ti.\"",
  str_book_title_skin_10082 = "Colores Florecientes",
  str_book_skin_info_10082 = "\"May toda la belleza del mundo baile a tu nombre, y May tu sabio liderazgo florezca por mil años.\"",
  str_book_title_skin_10084 = "Observador Yingel",
  str_book_skin_info_10084 = "\"Como puedes ver, estoy observando a Rediesel Wrench en su hábitat natural.\"",
  str_book_title_skin_10085 = "Actuando con Barbara",
  str_book_skin_info_10085 = "¡El concierto de Barbara comienza con una explosión! ¿\"La Última Caelestita\" realmente está debutando con ella?",
  str_book_title_skin_10086 = "Jeriah en la playa",
  str_book_skin_info_10086 = "\"Ya sea tú o nuestro entorno... Todo es nuevo para mí.\"",
  str_book_title_skin_10087 = "Estrella del banquete",
  str_book_skin_info_10087 = "\"Acercarse a él es perfectamente aceptable, pero les pido que se comporten con un poco más de dignidad.\"",
  str_book_title_skin_10088 = "Silueta de Iluminación Iluminada",
  str_book_skin_info_10088 = "\"Como Gran Mariscal de la Federación Illumina... prometo velar por todo.\"",
  str_book_title_skin_10090 = "Inflexible al Tiempo",
  str_book_skin_info_10090 = "\"Los niños de la segunda legión... ¿Se han convertido en las estrellas que iluminan el camino de los demás?\"",
  str_book_title_skin_10091 = "Gemelas de la Flor Blanca",
  str_book_skin_info_10091 = "\"Nos parecemos tanto; incluso nuestros padres tienen dificultades para distinguirnos...\"",
  str_book_title_skin_10092 = "Carrera en la arena",
  str_book_skin_info_10092 = "\"La pistola ahora dispara agua en lugar de llamas. Si... solo este tipo de diversión pudiera durar para siempre. Un águila aún puede volar alto incluso con sus garras guardadas.\"",
  str_book_title_skin_10095 = "El día perezoso de Ryza",
  str_book_skin_info_10095 = "\"¿Me llamaste? ¿Qué pasa?\"",
  str_book_title_skin_10096 = "Los Fuegos Artificiales en Sus Ojos",
  str_book_skin_info_10096 = "\"Los fuegos artificiales pueden ser breves, pero siempre parpadearán en mi corazón.\"",
  str_book_title_skin_10097 = "El Dignatario Empapado",
  str_book_skin_info_10097 = "\"Quiero decir, si me pidieras tan sinceramente como lo hiciste antes, yo, un noble, podría dedicar un poco de tiempo para divertirme contigo.\"",
  str_book_title_skin_10099 = "Encuentro Casual: Bola de Nieve",
  str_book_skin_info_10099 = "\"Por favor, sigue la dirección hacia la que te estoy guiando. Siente la flotación de las olas. No tengas miedo, tomaré tu mano.\"",
  str_book_skin_info_laisha = "Ryza's Lazy Day",
  str_book_title_skin_laisha = "\"¡¿Qué ocurre?\"",
  str_book_skin_info_laisha1 = "The Fireworks in Her Eyes",
  str_book_title_skin_laisha2 = "\"Fireworks may be brief, but they'll forever flicker in my heart.\"",
  str_book_info_laisha1 = "Cita Azotada por las Olas",
  str_book_title_laisha1 = "\"¿Pensé que estábamos jugando, no es así? Mejor muévete, ¡o realmente te lo haré saber! ¡Jajá!\"",
  str_book_info_laisha2 = "Reunión de pensamientos",
  str_book_title_laisha2 = "\"¿Qué te parece? ¿Puedes sentir nuestra determinación ahora?!\"",
  str_book_info_laisha3 = "¡Nueva Aventura! ¡Levanta el Ancla!",
  str_book_title_laisha3 = "La isla yace silenciosamente en el fondo del mar, junto con las pruebas de su antigua gloria. Ahora, está a punto de comenzar una nueva aventura de verano.",
  str_book_title_skin_10100 = "Propuesta Ambiciosa",
  str_book_skin_info_10100 = "¿Quieres salir en una cita? ¡Recuerda traer suficientes monedas de oro!",
  str_book_title_skin_10101 = "Indulgencia carmesí",
  str_book_skin_info_10101 = "El Rey que Regresa del Banquete Carmesí",
  str_book_title_skin_10102 = "Trazos de acero",
  str_book_skin_info_10102 = "No te pongas nervioso, ¡toma primero una botella de solución nutritiva!",
  str_book_title_skin_10103 = "Lachesis avariciosa",
  str_book_skin_info_10103 = "\"Debajo de su encanto elegante y tentador, parpadea una luz codiciosa. Mantente alerta, ¡o ella arrebatará todo lo que aprecias!\"",
  str_book_info1113 = "Vivir libre o morir",
  str_book_title1113 = "\"Su 'corazón' arde sin cesar, nunca se cansa en su búsqueda de la libertad.\nDaría su vida por esta verdad.\n'Vive libre o muere', dijo Lady Pepita.\""
}
return config
